const rows = $input.all().map(i => i.json || {});
const snippets = rows.filter(r => r.text).map(r => ({
  id: r.id,
  doc_id: (r.metadata && r.metadata.doc_id) || '',
  product: (r.metadata && r.metadata.product) || 'General',
  title: (r.metadata && r.metadata.title) || (r.metadata && r.metadata.source_name) || 'doc',
  url: (r.metadata && r.metadata.url) || '',
  source: (r.metadata && r.metadata.source) || '',
  mime: (r.metadata && r.metadata.mime) || '',
  visibility: (r.metadata && r.metadata.visibility) || 'context_only',
  tenant_slug: (r.metadata && r.metadata.tenant_slug) || 'levinnovation',
  text: String(r.text || '').slice(0, 800),
  score: Math.round((r.score || 0) * 1000) / 1000
}));
const kbContext = snippets.map((s, idx) => `#${idx + 1} [${s.product}] ${s.title} ${s.url ? '('+s.url+')' : ''}\n${s.text}`).join('\n\n');
return [{ json: { kb_context: kbContext, snippets, hit_count: snippets.length } }];

const q = $json.query || {};
const tenantRaw = String(q.tenant || q.tenant_slug || 'levinnovation').trim().toLowerCase();
const docIdRaw = String(q.doc_id || '').trim();
const tenant = tenantRaw.replace(/[^a-z0-9-_]/g, '') || 'levinnovation';
const docId = docIdRaw.replace(/[^a-zA-Z0-9-]/g, '');
return [{ json: { tenant, doc_id: docId } }];

const row = ($input.first() || {}).json || {};
const hasRow = Boolean(row.id);
if (!hasRow) {
  return [{ json: { status_code: 404, download_body: 'Document not found or not shareable.' } }];
}
const title = String(row.title || 'document');
const content = String(row.raw_text || '').trim();
const header = `LEV Innovation Document: ${title}\n\n`;
const body = (header + content).slice(0, 200000);
return [{ json: { status_code: 200, download_body: body } }];
